import 'package:flutter_test/flutter_test.dart';
import 'package:skeen/features/detection/domain/capture_standard.dart';
import 'package:skeen/features/detection/domain/fiducial_marker.dart';
import 'package:skeen/features/detection/domain/study_protocol.dart';
import 'package:skeen/features/detection/infrastructure/marker_card_pdf.dart';

/// WP-5 — the printed card is derived from the same constants the detector
/// and the calibration use. These pin that derivation; the PDF itself is
/// generated by `tool/generate_marker_card.dart`.
void main() {
  final layout = MarkerCardLayout();
  final m = FiducialMarker.study;

  group('card layout is the marker definition, in millimetres', () {
    test('the code is exactly the marker\'s physical side', () {
      expect(layout.markerRect.width, m.sideMm);
      expect(layout.markerRect.height, m.sideMm);
    });

    test('cells tile the code with no gap and the right count', () {
      const n = FiducialMarker.cellsPerSide;
      expect(layout.cellRect(0, 0).topLeft, layout.markerRect.topLeft);
      expect(layout.cellRect(n - 1, n - 1).bottomRight.dx,
          closeTo(layout.markerRect.right, 1e-9));
      expect(layout.cellRect(n - 1, n - 1).bottomRight.dy,
          closeTo(layout.markerRect.bottom, 1e-9));
      expect(layout.cellRect(0, 0).width, closeTo(m.cellMm, 1e-9));
    });

    test('the quiet zone is one cell of paper all round', () {
      final q = layout.quietRect;
      expect(q.width, closeTo(m.sideMm + 2 * m.cellMm, 1e-9));
      expect(q.left, greaterThanOrEqualTo(0));
      expect(q.top, greaterThanOrEqualTo(0));
    });

    test('patches print where the sampler will look for them', () {
      // Same plane-frame geometry as ColorPatch, translated to the card.
      final greyCentre = layout.greyPatchRect.center - layout.markerCentre;
      final whiteCentre = layout.whitePatchRect.center - layout.markerCentre;
      expect((greyCentre - m.greyPatch.centreMm).distance, lessThan(1e-9));
      expect((whiteCentre - m.whitePatch.centreMm).distance, lessThan(1e-9));
      expect(layout.greyPatchRect.width, FiducialMarker.patchSideMm);
      // Outside the quiet zone.
      expect(layout.greyPatchRect.left, greaterThan(layout.quietRect.right));
    });

    test('the arrow points to where the target disc will be', () {
      // The disc is above the card, on skin; the arrow sits between the
      // quiet zone and the disc and points at it.
      final disc = layout.discCentre;
      expect(layout.arrowTip.dy, lessThan(layout.arrowBase.dy), reason: 'up');
      expect(layout.arrowTip.dx, closeTo(disc.dx, 1e-9));
      expect(disc.dy, lessThan(layout.arrowTip.dy), reason: 'disc beyond tip');
      expect(disc.dy, lessThan(layout.quietRect.top));
      expect(TargetDisc.clearanceMm(), greaterThan(0));
    });

    test('the verification ruler is exactly 30 mm', () {
      expect(layout.rulerEnd.dx - layout.rulerStart.dx, 30.0);
      expect(layout.rulerEnd.dy, layout.rulerStart.dy);
    });

    test('everything fits inside the cut line', () {
      final card = layout.cardRect;
      for (final r in [
        layout.quietRect,
        layout.greyPatchRect,
        layout.whitePatchRect,
      ]) {
        expect(card.contains(r.topLeft), isTrue);
        expect(card.contains(r.bottomRight), isTrue);
      }
      expect(card.contains(layout.rulerEnd), isTrue);
      expect(card.contains(layout.arrowTip), isTrue);
    });

    test('the card is credit-card sized, not a poster', () {
      expect(layout.cardRect.width, lessThan(70));
      expect(layout.cardRect.height, lessThan(110));
    });
  });

  group('protocol text', () {
    test('the placement instruction does not describe a purpose', () {
      // Blinding: the card is in both arms, so the wording must not hint
      // that it "does" anything.
      final text = kMarkerPlacementInstruction.toLowerCase();
      for (final word in ['medir', 'mide ', 'calibr', 'guía', 'guia', 'app', 'detect']) {
        expect(text.contains(word), isFalse, reason: 'must not contain "$word"');
      }
      expect(text, contains('flecha'));
      expect(text, contains('3 mm'));
    });

    test('the print check names the exact length', () {
      expect(kPrintScaleCheckInstruction, contains('30 mm'));
      expect(kPrintScaleCheckInstruction, contains('100 %'));
    });
  });

  test('the PDF builds', () async {
    final bytes = await buildMarkerCardPdf();
    expect(bytes.length, greaterThan(1000));
    // PDF magic.
    expect(String.fromCharCodes(bytes.take(4)), '%PDF');
  });
}
